package com.rishitgoklani.hermes_front_mobile.data.avatar

import com.rishitgoklani.hermes_front_mobile.domain.avatar.library.AvatarFiles
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File

/** Models in `<root>/<id>.vrm`, thumbnails in `<root>/thumbs/<id>.png`. Ids are generated by the app (UUID); anything else is refused so a path can never escape [root]. */
class FileAvatarFiles(private val root: File) : AvatarFiles {
    private fun model(id: String) = File(root, "${safe(id)}.vrm")
    private fun thumb(id: String) = File(File(root, "thumbs"), "${safe(id)}.png")
    private fun safe(id: String): String { require(id.isNotEmpty() && id.all { it.isLetterOrDigit() || it == '-' || it == '_' }) { "bad avatar id" }; return id }

    override suspend fun write(id: String, bytes: ByteArray) = withContext(Dispatchers.IO) {
        root.mkdirs(); val tmp = File(root, "${safe(id)}.vrm.tmp"); tmp.writeBytes(bytes)
        check(tmp.renameTo(model(id))) { "could not save model" }
    }
    override suspend fun read(id: String): ByteArray? = withContext(Dispatchers.IO) { model(id).takeIf { it.isFile }?.readBytes() }
    override fun modelPath(id: String): String? = model(id).takeIf { it.isFile }?.path
    override suspend fun writeThumb(id: String, png: ByteArray): String = withContext(Dispatchers.IO) { val f = thumb(id); f.parentFile?.mkdirs(); f.writeBytes(png); f.path }
    override suspend fun delete(id: String) { withContext(Dispatchers.IO) { model(id).delete(); thumb(id).delete() } }
}
